-- GENERATED by `wfj generate` from data/gossip/gossip-05.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["05057a8760dc4bd9"] = { "Quale corruzione?", "." },
  ["050757fc2aaea724"] = { "Gli spiriti della foresta sono inquieti...", "." },
  ["0512aebdd47e463f"] = { "Guarda il nemico, {race}. Guarda a cosa la potenza dell'⟦Horde=Orda⟧ riduce persino il più potente dei draghi! Tutti coloro che si oppongono a noi faranno la stessa fine!", "." },
  ["0512d6a66edf753e"] = { "Coraggio, amici. Il rettile si dimenerà furiosamente. È un atto di disperazione. Quando siete pronti, datemi il via.", "." },
  ["0519343ef6609bcc"] = { "Vieni a parlare con me se commerci in cose insolite, o se hai delle Carte di Lunacupa.", "." },
  ["051d84b7eb10786c"] = { "Il ricordo della mia bellezza rende la sua perdita insopportabile!", "." },
  ["052050fc7f01b624"] = { "Dovrei tornare prima che Rema cominci a preoccuparsi...", "." },
  ["05214ec63c078db0"] = { "Ben <trovato/trovata>, {class}. Spero che tu sia qui per informarti sullo sforzo bellico per ⟦Ahn'Qiraj=Ahn'qiraj⟧. Avremo bisogno di moltissimo aiuto.\n\nLo sforzo bellico è un impegno comune dell'⟦Alliance=Alleanza⟧ e dell'⟦Horde=Orda⟧ per prepararsi all'imminente guerra contro i Silitidi e i loro padroni ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Nel Quartiere Militare di ⟦Ironforge=Forgiardente⟧ stiamo raccogliendo merci di ogni genere da cui ricavare il nostro materiale bellico, ed è in queste raccolte che ci serve il tuo aiuto.\n\nPosso convincerti a parlare con il nostro comandante per dare una mano?", "." },
  ["052b8a864e12ce50"] = { "Le cariche sono piazzate. Indietro prima che esplodano!", "." },
  ["05321ea1b50c93d8"] = { "Cosa?", "." },
  ["0533e98302158e7f"] = { "Mio fratello e io siamo impegnati in una missione vitale, ma siamo bloccati in questa fattoria. Gli ⟦Deathstalkers=Inseguitori della Morte⟧ hanno bisogno del tuo aiuto.", "." },
  ["05348629335d2085"] = { "Certamente, {name}.\n\nGli avventurieri che l'Alba considera onorati devono consegnare in tutto 40 insegne per accedere agli oggetti superiori. Per accedere a oggetti di potere ancora maggiore, dovrebbero consegnarne in tutto 150.\n\nDevo ammettere che il prezzo è alto anche per chi è onorato presso l'Alba.", "." },
  ["0535355a1ab32258"] = { "Forza, ragazzi, dobbiamo ricostruire questo ponte.", "." },
  ["0539777c35f2814c"] = { "Qui c'è una pila di regali incartati.", "." },
  ["05409cbc9ec0973c"] = { "Avverto un pericolo nel profondo del bosco...", "." },
  ["0548e40805990a8d"] = { "Mmm, questo sembra qualcosa che starebbe meglio come scacciapensieri. Prendete appunti, classe... Questo NON è ciò che volete evocare nel pieno della battaglia.", "." },
  ["0549a0847cf42369"] = { "Il ⟦The Razza=Razza⟧ ha appena fatto altro fertilizzante per Mushgog!", "." },
  ["055549f04f048bf2"] = { "Ne ho la certezza al 100%: voglio imparare le vie dell'ingegneria goblin.", "." },
  ["055de74867e0a935"] = { "Le bestie di queste terre devastate mostrano qualità preternaturali, mai viste prima in natura.\n\nAbbiamo ipotizzato che l'energia sprigionata all'apertura del Portale Oscuro sia penetrata nel loro corpo, costringendo le creature a evolversi nelle forme attuali.\n\nSono bestie temibili, senza dubbio, ma crediamo anche che potrebbero rivelarsi assai utili per i nostri studi.\n\nTi interesserebbe aiutarci a studiare queste bestie, {name}?", "." },
  ["05667dffdf99128c"] = { "%s inizia a ribollire!", "." },
  ["0566d1a766d7ca63"] = { "Prima di lasciare questo luogo, ti faccio un'ultima offerta, sire Staghelm. Se mai dovesse giungere il momento in cui dovrai entrare in questa fortezza maledetta, usa lo Scepter of the Shifting Sands sul gong sacro. La magia che tiene unita la barriera si dissolverà e gli orrori di ⟦Ahn'Qiraj=Ahn'qiraj⟧ si scateneranno di nuovo sul mondo.", "." },
  ["0568fadc25bc30a2"] = { "Spero che la tua interruzione sia per una buona causa. Ero nel bel mezzo di un lavoro importante.", "." },
  ["056b3adc8317e5b7"] = { "Gli gnomi possono essere difficili da colpire per via della loro taglia. Però hanno un debole per la danza e per ancheggiare. Quando lo fanno, colpiteli così...", "." },
  ["0576391e86c79352"] = { "%s emerge dall'oscurità, attirato dal visore divinatorio!", "." },
  ["05777ffd3aa9369a"] = { "Le tue intromissioni finiscono qui, {name}! ⟦Lord Valthalak=Sire Valthalak⟧ avrà la sua vendetta!", "." },
  ["058847dfa3bd67cf"] = { "Vuoi imparare l'antica arte? Vuoi fondere il Ferroscuro?\n\nPlacami, {race}. Mostrami un sacrificio e ci penserò!", "." },
  ["058ac63036845401"] = { "Le nostre forze nella ⟦Alterac Valley=Valle d'Alterac⟧ hanno bisogno di saggezza per vincere, {class}. Hai l'aria di chi può guidarle.", "." },
  ["058db46af9f3c19e"] = { "Mia arma avere sete!", "." },
  ["059016173c5e548a"] = { "La vostra base è perduta, miseri mortali!", "." },
  ["059880d0c7a604bc"] = { "Il clan dei Piccatonante non si inchina a nessuno, men che meno all'Orda!", "." },
  ["059931e76084837b"] = { "Che cos'hai lì, {class}? Un bocconcino gustoso?", "." },
  ["059d1ee446e3bef0"] = { "Poiché la lama non è mai abbastanza affilata né l'armatura abbastanza robusta, ci sarà sempre bisogno di un incantatore di talento. Un incantatore così è Taladan, che può mostrarti come intessere a dovere gli incantamenti per migliorare armi e armature. Cercalo nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧.", "." },
  ["059da8ba7eca6811"] = { "Cani del ⟦Cenarion Circle=Circolo Cenariano⟧. Uccideteli tutti!", "." },
  ["05a582cde9aa5c98"] = { "Continua la tua storia.", "." },
  ["05aad4834b4e4f4d"] = { "Brom Killian insegna te come scavare roba luccicante per me. Lui su anello interno di ⟦War Quarter=Quartiere della Guerra⟧.", "." },
  ["05ac908a43d2bdf3"] = { "Folle {name}, ora servi me!", "." },
  ["05b18b4e7c5122a8"] = { "Sarà per la prossima volta, {name}.", "." },
  ["05ba76ca917d1353"] = { "Lee ha pescato roba piuttosto strana su al ⟦Crystal Lake=Lago di Cristallo⟧. Mi ha raccontato di una maschera bizzarra che ha tirato su qualche mese fa. Se vuoi il mio parere, quella sera al Lion's Pride ha alzato un po' troppo il gomito.", "." },
  ["05bc3297103a996c"] = { "Mettiamoci al lavoro, {name}!", "." },
  ["05c080b6a0ef9606"] = { "Forse dovrei dirti perché sono qui.\n\nConosci l'Aspetto Alamorte? O la sua progenie, Nefarian e Onyxia?", "." },
  ["05c67f80fbb215f3"] = { "La tua abilità non è da poco. Visto che sembri avere abbastanza esperienza, c'è una faccenda per cui mi serve il tuo aiuto.", "." },
  ["05cf2f558b1e4000"] = { "Il Signore delle Acque Idraxis si nasconde ad Azshara, su un'isola nella ⟦Bay of Storms=Baia delle Tempeste⟧. Che razza di minaccia può mai radunare quello sciocco da laggiù?", "." },
  ["05d1504239c6f66d"] = { "Sento piccoli cuori che battono. Sì... battono più forte, ora... presto il battito si fermerà.", "." },
  ["05e8e5c161e7fb5f"] = { "C'è dell'altro.", "." },
  ["05f0416731b6a25c"] = { "Betina, vorrei una ⟦Rune of the Dawn=Runa dell'Alba⟧ nuova, per favore!", "." },
  ["05f36b78ace0504b"] = { "Se lo desideri, oltre all'addestramento, ho il potere di cancellare dalla tua mente la conoscenza dei tuoi talenti. Ma sappi che ogni volta che ti sottoponi a questa procedura diventa più difficile da eseguire, e quindi più costosa.", "." },
  ["05f5dd520b046452"] = { "Sta' lontano da Sumi e Tumi. Hanno... già qualcuno.", "." },
  ["05fdd5a7ca0d7f36"] = { "Arr, compare! Guadagnare un solo ninnolo non basta a fare di te un maestro dell'Arena! Ora è il momento di dimostrare davvero quanto vali.", "." },
})
